mapper.select:
select * from approval_flow_definition where corpid = #{corpid} and del = 0
and business_code = #{businessCode}
and approval_scene = #{approvalScene}
order by business_code, approval_scene, priority, version desc

select coalesce(max(version), 0)
from approval_flow_definition
where corpid = #{corpid}
  and business_code = #{businessCode}
  and approval_scene = #{approvalScene}
  and flow_code = #{flowCode}

mapper.update:
update approval_flow_definition
set flow_name = #{flowName}, priority = #{priority}, status = #{status}, scope_json = #{scopeJson}, modify_id = #{modifyId}, update_time = #{updateTime}
where corpid = #{corpid} and id = #{id} and del = 0

update approval_flow_definition
set del = 1,
    modify_id = #{modifyId},
    update_time = #{updateTime}
where corpid = #{corpid}
  and id = #{id}
  and del = 0
